const fetchMeta = $('Pre-Works Fetch Summary1').first().json || {};
const html = ($('Fetch Pre-Works Table HTML1').first().json || {}).html || '';
const WO_UPLOAD_SUFFIX = '_wi_pw_24819_upload';
const WO_NOTES_SUFFIX = '_wi_pw_24819_notes';
const UPRN_SUFFIX = '_property_ref';
const ADDR_SUFFIX = '_address';
const CORF_SUFFIX = '_client_order_reference';

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const under = t.match(/^(\d+)_(\d+)$/);
  if (under) return parseInt(under[1], 10) + '/' + parseInt(under[2], 10);
  return t;
}
function cellClass(attrs) {
  const m = String(attrs || '').match(/class="([^"]*)"/i);
  if (!m) return '';
  return m[1].split(/\s+/).find(c => c.startsWith('jqgrid_bg_')) || '';
}
function cellTitle(attrs) {
  const m = String(attrs || '').match(/title="([^"]*)"/i);
  return m ? m[1].trim() : '';
}

const preWorksWoByCorf = {};
const redRows = [];
let greenCount = 0;

const trRegex = /<tr[^>]+id="(\d+)"[^>]*>([\s\S]*?)<\/tr>/gi;
let trMatch;
while ((trMatch = trRegex.exec(html)) !== null) {
  const rowId = trMatch[1];
  const rowHtml = trMatch[2];
  const cells = {};
  const tdRegex = /<td([^>]+)>([\s\S]*?)<\/td>/gi;
  let tdMatch;
  while ((tdMatch = tdRegex.exec(rowHtml)) !== null) {
    const keyMatch = tdMatch[1].match(/aria-describedby="([^"]+)"/i);
    if (!keyMatch) continue;
    cells[keyMatch[1]] = { attrs: tdMatch[1] };
  }
  function getCell(suffix) {
    for (const [key, val] of Object.entries(cells)) {
      if (key.endsWith(suffix)) return val;
    }
    return null;
  }
  const woCell = getCell(WO_UPLOAD_SUFFIX) || getCell(WO_NOTES_SUFFIX);
  if (!woCell) continue;
  const woClass = cellClass(woCell.attrs);
  const corfRaw = cellTitle(getCell(CORF_SUFFIX)?.attrs);
  const corf = normCorf(corfRaw) || normCorf(corfRaw.replace(/_/g, '/'));
  if (!corf) continue;

  const isRed = woClass.includes('red');
  const isGreen = woClass.includes('green');
  const status = isRed ? 'red' : (isGreen ? 'green' : 'other');
  preWorksWoByCorf[corf] = {
    status,
    corf_raw: corfRaw || corf,
    pre_work_id: rowId,
    address: cellTitle(getCell(ADDR_SUFFIX)?.attrs),
    uprn: cellTitle(getCell(UPRN_SUFFIX)?.attrs),
    wo_upload_class: woClass,
  };
  if (isGreen) greenCount++;
  if (isRed) {
    redRows.push({
      pre_work_id: rowId,
      uprn: cellTitle(getCell(UPRN_SUFFIX)?.attrs),
      address: cellTitle(getCell(ADDR_SUFFIX)?.attrs),
      client_order_reference: corfRaw || corf,
      corf,
      wo_upload_class: woClass,
    });
  }
}

const sd = $getWorkflowStaticData('global');
sd.preWorksWoByCorf = preWorksWoByCorf;

console.log(
  `${fetchMeta.verify_message || ''} | pre-works WO green=${greenCount} red=${redRows.length} total_corfs=${Object.keys(preWorksWoByCorf).length}`
);

if (!redRows.length) {
  return [{
    json: {
      _no_red_rows: true,
      red_count: 0,
      green_count: greenCount,
      message: 'No red Global Works Order Form rows — greens synced separately.',
    },
  }];
}
return redRows.map(r => ({ json: r }));

function normCorf(v) {
