}
function isEasybopDone(raw) {
  const s = String(raw ?? '').trim().toLowerCase();
  if (!s) return false;
  return s === 'true' || s === '1' || s === 'yes' || s === 'uploaded' || s === 'done';
}

const sd = $getWorkflowStaticData('global');
const preWorks = sd.preWorksWoByCorf || {};
const sheetRows = $('Read Work Order Form1').all().map(i => i.json || {});

const updates = [];
for (const row of sheetRows) {
  const corfKey = normCorf(row.CORF);
  if (!corfKey) continue;
  if (isEasybopDone(row['.msg on easybop'])) continue;
  const pw = preWorks[corfKey];
  if (!pw || pw.status !== 'green') continue;
  updates.push({
    CORF: row.CORF ?? corfKey,
    '.msg on easybop': 'TRUE',
    _sheet_update_reason: 'already_green_on_preworks',
  });
}

console.log(`Sheet sync (pre-works green): ${updates.length} row(s) to mark TRUE`);

if (!updates.length) {
  return [{ json: { _no_sheet_updates: true, _phase: 'preworks_green' } }];
}
return updates.map(u => ({ json: u }));

