const sheetRows = $('Read Work Order Form1').all().map(i => i.json || {});
const sheetByCorf = {};
for (const row of sheetRows) {
  const k = normCorf(row.CORF);
  if (k) sheetByCorf[k] = row;
}

const results = $('Expand Batch Results3').all().map(i => i.json || {});
const updates = [];
const seen = new Set();

for (const r of results) {
  if (!r._api_success) continue;
  const k = normCorf(r.corf);
  if (!k || seen.has(k)) continue;
  const sheet = sheetByCorf[k];
  if (!sheet) continue;
  if (isEasybopDone(sheet['.msg on easybop'])) continue;
  seen.add(k);
  updates.push({
    CORF: sheet.CORF ?? k,
    '.msg on easybop': 'TRUE',
    _sheet_update_reason: r._already_uploaded ? 'already_on_easybop_api' : 'uploaded_this_run',
  });
}

console.log(`Sheet sync (after upload): ${updates.length} row(s) to mark TRUE`);

if (!updates.length) {
  return [{ json: { _no_sheet_updates: true, _phase: 'after_upload' } }];
}
return updates.map(u => ({ json: u }));

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && body.body && body.items === undefined && body.total === undefined) {
    body = body.body;
  }
  return body || {};
}
function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}
function cleanAddrKey(str) {
  return String(str || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
const resp = $input.first().json || {};
const data = bodyFrom(resp);
const items = Array.isArray(data.items) ? data.items : [];
const corfToWorksId = {};
const addrToWorksId = {};
for (const item of items) {
  const wid = String(item.works_id || '').trim();
  if (!wid) continue;
  const corf = normCorf(item.client_order_reference || '');
  if (corf) corfToWorksId[corf] = wid;
  const addr = cleanAddrKey(item.address || '');
  if (addr) addrToWorksId[addr] = wid;
}
const sd = $getWorkflowStaticData('global');
sd.corfToWorksId = corfToWorksId;
sd.addrToWorksId = addrToWorksId;
return [{
  json: {
    works_index_total: data.total ?? items.length,
    works_index_ok: data.success === true,
    corf_map_size: Object.keys(corfToWorksId).length,
    message: data.message || `Indexed ${items.length} works`,
  },
}];

const driveId = $('Get BCC library drive2').first().json.id;
const SP_FOLDER = 'RR Job imports and JIS/Orders/RR-South/inbox';
const spFiles = ($('List RR-South inbox1').first().json.value || []).filter(f => f.file && f.name.toLowerCase().endsWith('.msg'));
const rows = $('Parse Pre-Works WO Status').all().map(i => i.json || {}).filter(r => !r._no_red_rows);
const sd = $getWorkflowStaticData('global');
const corfToWorksId = sd.corfToWorksId || {};

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const under = t.match(/^(\d+)_(\d+)$/);
  if (under) return parseInt(under[1], 10) + '/' + parseInt(under[2], 10);
  return t;
}

function corfFromSpFileName(name) {
  const n = String(name || '');
  let m = n.match(/WO[_\s]*Ref[_\s]*(\d+)[_\s\/\\-]+(\d+)/i);
  if (m) return normCorf(parseInt(m[1], 10) + '/' + parseInt(m[2], 10));
  m = n.match(/(\d{4,6})[_\s](\d+)/);
  if (m) return normCorf(parseInt(m[1], 10) + '/' + parseInt(m[2], 10));
  return '';
}

function cleanWoMsgFileName(corf) {
  const c = String(corf || '').trim();
  return `Works_Order_Details_for_WO_Ref_${c}.msg`;
}

const corfToFile = {};
for (const f of spFiles) {
  const c = corfFromSpFileName(f.name);
  if (c && !corfToFile[c]) corfToFile[c] = f;
}

const pending = [];
const skipped = [];

for (const row of rows) {
  const corfRaw = String(row.client_order_reference || '').trim();
  const corf = normCorf(corfRaw) || corfRaw;
  if (!corf) {
    skipped.push({ pre_work_id: row.pre_work_id, reason: 'no_corf', address: row.address });
    continue;
  }
  const spFile = corfToFile[corf];
  if (!spFile) {
    skipped.push({ pre_work_id: row.pre_work_id, corf, address: row.address, reason: 'no_sharepoint_msg' });
    continue;
  }
  const works_id = corfToWorksId[corf] || '';
  if (!works_id) {
    skipped.push({ pre_work_id: row.pre_work_id, corf, address: row.address, reason: 'no_works_id', sp_file: spFile.name });
    continue;
  }
  const uploadName = cleanWoMsgFileName(corf);
  pending.push({
    json: {
      _skip: false,
      pre_work_id: row.pre_work_id,
      corf: corfRaw || corf,
      works_id,
      address: row.address || '',
      uprn: row.uprn || '',
      sp_file_id: spFile.id,
      sp_file_name: spFile.name,
      upload_file_name: uploadName,
      download_url: `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${spFile.id}/content`,
    },
  });
}

if (pending.length === 0) {
  return [{ json: { _skip: true, message: 'No pending WO .msg uploads.', skipped_count: skipped.length, skipped } }];
}
return pending;

// Process each download with explicit item index so binary + metadata stay paired.
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const row = { ...(item.json || {}) };
  if (row._skip) {
    out.push({ json: { ...row, _skip: true } });
    continue;
  }
  const corf = String(row.corf || '').trim();
  const spFile = String(row.sp_file_name || '').trim();
  const bin = item.binary || {};
  const binKey = bin.data ? 'data' : Object.keys(bin)[0];
  if (!binKey) {
    out.push({ json: { ...row, _encode_error: `No binary for CORF ${corf}${spFile ? ` (${spFile})` : ''}`, _skip: true } });
    continue;
  }

  let buffer;
  try {
    buffer = await this.helpers.getBinaryDataBuffer(i, binKey);
  } catch (e) {
    out.push({ json: { ...row, _encode_error: `No binary for CORF ${corf}: ${e.message}`, _skip: true } });
    continue;
  }

  const size = buffer.length;
  if (size < 256) {
    out.push({ json: { ...row, _encode_error: `MSG too small (${size} bytes)`, _skip: true } });
    continue;
  }
  const ole = buffer.slice(0, 4).toString('hex') === 'd0cf11e0';
  const head = buffer.slice(0, 512).toString('latin1').toLowerCase();
  const mime = head.includes('mime-version:') || head.includes('received:');
  if (!ole && !mime) {
    out.push({ json: { ...row, _encode_error: `Not a valid .msg for CORF ${corf}`, _skip: true } });
    continue;
  }
  out.push({ json: { ...row, _msg_base64: buffer.toString('base64'), _msg_size: size, _skip: false } });
}

return out;

const raw = $input.first().json || {};
const html = String(raw.html || '');
const ids = [];
const re = /<tr[^>]+id="(\d+)"/gi;
let m;
while ((m = re.exec(html)) !== null) ids.push(m[1]);
const unique = [...new Set(ids)];
const pages = raw.pages_scraped;
const rowsApi = raw.rows_total;
return [{
  json: {
    success: raw.success !== false,
    pages_scraped: pages ?? null,
    rows_total_api: rowsApi ?? null,
    rows_counted_in_html: unique.length,
    verify_message: `pages_scraped=${pages ?? '?'} | rows_total=${rowsApi ?? '?'} | counted=${unique.length}`,
  },
}];

const apiBase = String($('Set API URL3').first().json.api_base_url || '').replace(/\/+$/, '');
const rows = $('Encode MSG Base').all();
const items = [];
const batchMeta = [];
const skipped = [];
const seenB64 = new Map();
for (const item of rows) {
  const j = item.json || {};
  const base = { pre_work_id: j.pre_work_id, corf: j.corf, works_id: j.works_id };
  if (j._skip) {
    skipped.push({ ...base, _status: `ERROR: ${j._encode_error || 'Skipped'}`, _api_success: false });
    continue;
  }
  const corf = String(j.corf || '').trim();
  const wid = String(j.works_id || '').trim();
  const fileName = String(j.upload_file_name || '').trim();
  const b64 = String(j._msg_base64 || '').trim();
  if (!corf || !wid || !fileName || !b64) {
    skipped.push({ ...base, _status: 'ERROR: Missing corf/works_id/file/base64', _api_success: false });
    continue;
  }
  const dupCorf = seenB64.get(b64);
  if (dupCorf) {
    skipped.push({ ...base, _status: `ERROR: Duplicate MSG content for CORF ${corf} (same bytes as ${dupCorf})`, _api_success: false });
    continue;
  }
  seenB64.set(b64, corf);
  items.push({ corf, works_id: wid, file_name: fileName, msg_base64: b64 });
  batchMeta.push({ ...base, upload_file_name: fileName, sp_file_name: j.sp_file_name });
}
return [{
  json: {
    _api_url: `${apiBase}/wi-msg/upload-batch`,
    _skipped: skipped,
    _batch_meta: batchMeta,
    _batch_body: { items, contract_id: '321129', use_works_id_navigation: true, timeout_ms: 45000 },
    _item_count: items.length,
    _skipped_count: skipped.length,
  },
}];

const agg = $('Aggregate Batch Payload3').first().json;
const skipped = agg._skipped || [];
const batchMeta = agg._batch_meta || [];
const pendingByKey = {};
for (const item of $('Match SharePoint MSGs1').all()) {
  const j = item.json || {};
  if (j._skip) continue;
  const key = `${j.works_id}::${j.corf}`;
  pendingByKey[key] = j;
}
function resolvePending(meta) {
  const key = `${meta.works_id}::${meta.corf}`;
  return pendingByKey[key] || {};
}
function mapApiResult(r, meta) {
  const pending = resolvePending(meta);
  const msg = String(r.message || '').toLowerCase();
  const already = !!(r.already_uploaded || msg.includes('already present'));
  const ok = !!(r.success || r.uploaded || already);
  const status = ok ? 'true' : `ERROR: ${r.error || r.message || 'Unknown error'}`;
  return {
    pre_work_id: pending.pre_work_id ?? meta.pre_work_id,
    corf: r.corf || meta.corf || pending.corf,
    works_id: r.works_id || meta.works_id || pending.works_id,
    address: pending.address || '',
    sp_file_name: meta.sp_file_name || pending.sp_file_name || '',
    upload_file_name: meta.upload_file_name || pending.upload_file_name || '',
    _status: status,
    _api_success: ok,
    _already_uploaded: already,
    _newly_uploaded: !!r.uploaded,
  };
}
function extractResults(resp) {
  const statusCode = resp.statusCode ?? resp.status ?? 0;
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && typeof body === 'object' && body.body && !body.results) body = body.body;
  const results = Array.isArray(body?.results) ? body.results : [];
  return { statusCode, body: body || {}, results };
}
function markErrors(metaList, errMsg) {
  return metaList.map(meta => {
    const pending = resolvePending(meta);
    return {
      pre_work_id: pending.pre_work_id ?? meta.pre_work_id,
      corf: meta.corf,
      works_id: meta.works_id,
      address: pending.address || '',
      _status: `ERROR: ${errMsg}`,
      _api_success: false,
    };
  });
}
let apiResults = [];
if (agg._item_count > 0) {
  const postItems = $('POST wi-msg upload-batch1').all();
  const resp = postItems.length ? (postItems[0].json || {}) : ($input.first()?.json || {});
  const { results, statusCode, body } = extractResults(resp);
  if (results.length > 0) {
    for (let idx = 0; idx < results.length; idx++) {
      apiResults.push(mapApiResult(results[idx], batchMeta[idx] || {}));
    }
    if (results.length < batchMeta.length) {
      const tail = batchMeta.slice(results.length);
      apiResults.push(...markErrors(tail, `Batch interrupted (HTTP ${statusCode || 'unknown'})`));
    }
  } else if (batchMeta.length > 0) {
    const err = body.detail || body.message || body.error || `HTTP ${statusCode || 'connection failed'}`;
    apiResults.push(...markErrors(batchMeta, err));
  }
}
const all = [...skipped, ...apiResults];
return all.map(j => ({ json: j }));

const rows = $('Expand Batch Results3').all().map(i => i.json || {});
let newlyUploaded = 0, alreadyUploaded = 0, errors = 0;
const errorDetails = [];
for (const r of rows) {
  const status = String(r._status ?? '').trim();
  if (status === 'true') {
    if (r._already_uploaded) alreadyUploaded++;
    else newlyUploaded++;
  } else if (status.startsWith('ERROR:')) {
    errors++;
    errorDetails.push({ corf: r.corf, works_id: r.works_id, error: status });
  }
}
const greenSync = $('Sync Sheet Pre-Works Green').all().filter(i => !i.json?._no_sheet_updates).length;
const uploadSync = $('Prepare Sheet Updates From Upload').all().filter(i => !i.json?._no_sheet_updates).length;
return [{
  json: {
    workflow: 'pre_works_wo_msg_to_easybop',
    total_results: rows.length,
    newly_uploaded: newlyUploaded,
    already_on_easybop: alreadyUploaded,
    errors,
    sheet_marked_preworks_green: greenSync,
    sheet_marked_after_upload: uploadSync,
    error_details: errorDetails,
  },
}];
